from math import cos, sin, pi
from taf.hw.mcs.mcs import MCS
from taf.hw.api.hbte.hbte import PA
from taf.hw.mcs.exception import OutputGroupIdInvalid


class HBTE(MCS):

    _vendor = "HBTE"
    _model = None
    _version = None

    def __init__(self, ip=None, row_num=64, column_num=16, **kwargs):
        super(HBTE, self).__init__(**kwargs)
        self._pa = PA(ip)
        self._row_num = row_num
        self._column_num = column_num

    @property
    def row_num(self):
        return self._row_num

    def connect(self):
        pass

    def disconnect(self):
        pass

    def set_frequency(self, frequency, timeout=None):
        return self._pa.setCurrentFrePoints(frequency)

    def set_phases_according_to_angles(self, vertical_angle, horizontal_angle,
                                       vertical_distance, horizontal_distance,
                                       output_group_id, input_group_id):
        if output_group_id is None or output_group_id not in range(1, self._column_num + 1):
            raise OutputGroupIdInvalid(output_group_id)

        output_ids = [output_group_id]

        if input_group_id is None:
            input_ids = self._get_all_input_ids()
        else:
            input_ids = self._get_input_ids_by_group_id(input_group_id)

        channel_ids = []
        phases = []
        for input_id in input_ids:
            for output_id in output_ids:
                channel_ids.append(self._get_channel_id(input_id, output_id))
                polar_group_index = self._get_polar_group_index_by_input_id(input_id)
                row_group_index = self._get_row_group_index_by_input_id(input_id)
                phase = self._calc_phase_formula_value(vertical_angle, horizontal_angle,
                                                       vertical_distance, horizontal_distance,
                                                       polar_group_index, row_group_index)
                phases.append(phase)
        self._operate_channel_phase(channel_ids, phases)

    def _get_polar_group_index_by_input_id(self, input_id):
        raise NotImplementedError

    def _get_row_group_index_by_input_id(self, input_id):
        raise NotImplementedError

    def _get_all_input_ids(self):
        return list(range(1, self.row_num + 1))

    def _get_input_ids_by_group_id(self, input_group_id):
        raise NotImplementedError

    @staticmethod
    def _calc_phase_formula_value(vertical_angle, horizontal_angle, vertical_distance, horizontal_distance, n, m):
        vertical_angle = (vertical_angle * pi) / 180
        horizontal_angle = (horizontal_angle * pi) / 180
        phase = 2 * 180 * horizontal_distance * n * sin(vertical_angle) * sin(horizontal_angle) + \
            2 * 180 * vertical_distance * m * cos(vertical_angle)
        return round((phase + 360 * 3) % 360)

    def set_phase(self, phase, input_channel, output_channel):
        channel_id = self._get_channel_id(input_channel, output_channel)
        self._operate_channel_phase([channel_id], [phase])

    def get_phase(self, input_channel, output_channel):
        channel_id = self._get_channel_id(input_channel, output_channel)
        return self._query_channel_phase([channel_id])

    def set_phases(self, phase, begin_input_channel=1, end_input_channel=64, output_channel=1):
        channel_ids = [self._get_channel_id(input_id, output_channel)
                       for input_id in range(begin_input_channel, end_input_channel + 1)]
        phases = [phase] * len(channel_ids)
        self._operate_channel_phase(channel_ids, phases)

    def set_attenuation(self, attenuation, input_channel, output_channel):
        channel_id = self._get_channel_id(input_channel, output_channel)
        return self._operate_channel([channel_id], [attenuation])

    def get_attenuation(self, input_channel, output_channel):
        channel_id = self._get_channel_id(input_channel, output_channel)
        return self._query_channel([channel_id])

    def set_odd_attenuations(self, attenuation, begin_input_channel, end_input_channel, output_channel):
        channel_ids = []
        for input_channel in range(begin_input_channel, end_input_channel + 1):
            if input_channel % 2:
                channel_ids.append(self._get_channel_id(input_channel, output_channel))

        attenuations = [attenuation] * len(channel_ids)
        return self._operate_channel(channel_ids, attenuations)

    def set_even_attenuations(self, attenuation, begin_input_channel, end_input_channel, output_channel):
        channel_ids = []
        for input_channel in range(begin_input_channel, end_input_channel + 1):
            if input_channel % 2 == 0:
                channel_ids.append(self._get_channel_id(input_channel, output_channel))

        attenuations = [attenuation] * len(channel_ids)
        return self._operate_channel(channel_ids, attenuations)

    def _operate_channel(self, channels, values):
        return self._pa.operateChannel(channelList=channels, valueList=values)

    def _operate_multiple_channel(self, start_channel, end_channel, value):
        return self._pa.operateMulChannelPhase(startChannel=start_channel,
                                               endChannel=end_channel, phaseValue=value)

    def _operate_row(self, rows, value):
        return self._pa.operateRow(rows, value)

    def _operate_column(self, columns, value):
        return self._pa.operateColumn(columns, value)

    def _query_channel(self, channels):
        return self._pa.queryChannel(channels)

    def _operate_channel_phase(self, channels, phases):
        return self._pa.operateChannelPhase(channels, phases)

    def _operate_multiple_channel_phase(self, start_channel, end_channel, phase_value):
        return self._pa.operateMulChannelPhase(start_channel, end_channel, phase_value)

    def _operate_row_phase(self, rows, value):
        return self._pa.operateRowPhase(rows, value)

    def _operate_column_phase(self, columns, value):
        return self._pa.operateColumnPhase(columns, value)

    def _query_channel_phase(self, channels):
        return self._pa.queryChannelPhase(channels)

    def _reboot(self):
        return self._pa.reBootDevice()

    def _change_ip(self, addr, mask, gw):
        return self._pa.changeIP(addr, mask, gw)

    def _get_channel_id(self, input_channel, output_channel):
        if input_channel > self._row_num or output_channel > self._column_num:
            raise Exception("input ({0}) or output ({1}) channel are invalid".format(input_channel, output_channel))
        return (output_channel - 1) * self._row_num + input_channel
